package com.chatsystem.user.controller.report;import com.chatsystem.shared.service.ReportService;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class NewReportDialogController{private final ReportService reports;@FXML private TextField messageIdField,userIdField;@FXML private TextArea reasonField;@FXML private Label feedbackLabel;public NewReportDialogController(ReportService r){reports=r;}@FXML private void submit(){try{var result=reports.submitReport(Long.parseLong(messageIdField.getText().strip()),Long.parseLong(userIdField.getText().strip()),reasonField.getText());if(result.isSuccess())messageIdField.getScene().getWindow().hide();else feedbackLabel.setText(result.errors().get(0).message());}catch(RuntimeException e){feedbackLabel.setText("Enter valid message and user IDs");}}@FXML private void cancel(){messageIdField.getScene().getWindow().hide();}}
